#!/usr/bin/env bash
# install.py in a throwaway HOME and project: every CLI, both scopes, rerun,
# conflicts, hooks merge, links into dist, uninstall. Touches nothing outside a
# temp dir (ORC_DIST keeps the generated files out of this repo's dist/).
#   bash tests/test_install.sh
set -u
cd "$(dirname "$0")/.."
REPO=$PWD
pass=0; fail=0
check() { if eval "$2"; then pass=$((pass+1)); else fail=$((fail+1)); echo "FAIL: $1"; fi; }

T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
# Every location install.py reads from the environment, so nothing outside $T is touched.
export HOME=$T/home ORC_DIST=$T/dist; unset XDG_CONFIG_HOME CODEX_HOME GROK_HOME PI_CODING_AGENT_DIR HERDR_APP_HOME ORC_LEADS
mkdir -p "$HOME/.claude" "$HOME/.cursor/agents" "$HOME/.codex" "$HOME/.gemini/config" "$HOME/.agents/skills" "$T/proj"
# agy's skills folder linked to the shared one (as on many machines): one set of command skills.
ln -s "$HOME/.agents/skills" "$HOME/.gemini/config/skills"
# The user's own hooks in every CLI's hooks file: kept through install and uninstall.
echo '{"hooks": {"PreToolUse": [{"matcher": "Bash", "hooks": [{"type": "command", "command": "mine-codex.sh"}]}]}}' > "$HOME/.codex/hooks.json"
echo '{"version": 1, "hooks": {"preToolUse": [{"command": "mine-cursor.sh", "matcher": "Shell"}]}}' > "$HOME/.cursor/hooks.json"
echo '{"mine": {"PreInvocation": [{"command": "mine-agy.sh"}]}}' > "$HOME/.gemini/config/hooks.json"
echo '{"theme": "dark", "hooks": {"PreToolUse": [{"matcher": "Edit", "hooks": [{"type": "command", "command": "mine.sh"}]}]}}' > "$HOME/.claude/settings.json"
# A copy from before installs were links: ours, so it becomes a link.
echo '# Generated by herdr-orchestrators install.py from somewhere' > "$HOME/.cursor/agents/review-risk.md"
# --no-mods: never touch the real Claude plugin state; the mods get a dry-run check below.
I() { python3 "$REPO/install.py" --cli claude,opencode,agy,codex,cursor,grok,pi --no-mods "$@"; }

# 1. global install, every CLI
check "global install succeeds" "I >/dev/null"
for f in .claude/agents/hcorc.md .claude/agents/review-risk.md .claude/commands/herdorc-panes.md \
         .config/opencode/agents/herdorc.md .config/opencode/commands/hcorc-status.md \
         .gemini/config/agents/hcorc/agent.md .gemini/config/agents/jd-judge-a/agent.md \
         .codex/hcorc.config.toml .codex/agents/gentle-ai-worker.toml \
         .cursor/skills/herdorc/SKILL.md .cursor/skills/herdorc/prompt.md .cursor/agents/review-refuter.md \
         .grok/agents/hcorc.md .grok/agents/review-risk.md .grok/hooks/herdr-orchestrators.json \
         .pi/agent/herdr-orchestrators/herdorc.md .pi/agent/prompts/herdorc.md .pi/agent/prompts/hcorc-panes.md \
         .pi/agent/extensions/herdr-orchestrators-guard.ts; do
  check "installed $f as a link into dist" "[ -L '$HOME/$f' ] && [ \"\$(readlink '$HOME/$f')\" = '$ORC_DIST/home/$f' ] && [ -s '$HOME/$f' ]"
done
check "an old copy became a link" "[ -L $HOME/.cursor/agents/review-risk.md ] && grep -q '^readonly: true' $HOME/.cursor/agents/review-risk.md"
check "status counts links" "python3 '$REPO/install.py' --status | grep '^claude ' | grep -q 'links=' && ! python3 '$REPO/install.py' --status | grep -q -E 'BROKEN|copies='"
S=$HOME/.claude/settings.json
check "user settings kept (theme, own hook)" "python3 -c \"import json;d=json.load(open('$S'));assert d['theme']=='dark';assert any(h['hooks'][0]['command']=='mine.sh' for h in d['hooks']['PreToolUse'])\""
check "guard + phase hooks added once, absolute" "[ \$(grep -c 'shared/bin/guard.py' '$S') = 1 ] && grep -q '$REPO/shared/bin/orc.py phase --hook' '$S'"
check "settings backup written" "[ -f '$S.orc-backup' ]"

# 2. per-CLI content
# Guard parity: every CLI registers the guard in its own hook format, next to the user's hooks.
check "codex hooks: guard --format codex on ^Bash\$, user hook kept" "python3 -c \"import json;d=json.load(open('$HOME/.codex/hooks.json'))['hooks']['PreToolUse'];assert d[0]['hooks'][0]['command']=='mine-codex.sh';assert d[1]['matcher']=='^Bash\$' and d[1]['hooks'][0]['command'].endswith('guard.py --format codex')\""
check "cursor hooks: guard on beforeShellExecution, version kept, user hook kept" "python3 -c \"import json;d=json.load(open('$HOME/.cursor/hooks.json'));assert d['version']==1;assert d['hooks']['preToolUse'][0]['command']=='mine-cursor.sh';assert d['hooks']['beforeShellExecution'][0]['command'].endswith('guard.py --format cursor')\""
check "agy hooks: a named hook on run_command, user hook kept" "python3 -c \"import json;d=json.load(open('$HOME/.gemini/config/hooks.json'));assert 'mine' in d;h=d['herdr-orchestrators']['PreToolUse'][0];assert h['matcher']=='run_command' and h['hooks'][0]['command'].endswith('guard.py --format agy')\""
check "opencode guard plugin calls guard --format opencode" "[ -L $HOME/.config/opencode/plugins/herdr-orchestrators-guard.js ] && grep -q 'tool.execute.before' $HOME/.config/opencode/plugins/herdr-orchestrators-guard.js && grep -q '\"--format\", \"opencode\"' $HOME/.config/opencode/plugins/herdr-orchestrators-guard.js"
# OpenCode 2.x runs only a plugin's setup(); 1.x its server(). Both must refuse what the guard refuses.
cat > "$T/opencode-plugin.mjs" <<'EOF'
const plugin = (await import(process.argv[2])).default
const refused = async (call) => { try { await call(); return false } catch { return true } }
let hook
await plugin.setup({ tool: { hook: async (name, fn) => { if (name === "execute.before") hook = fn } } })
const v2 = (agent, command) => () => hook({ tool: "bash", sessionID: "s", agent, input: { command } })
const v1 = await plugin.server()
await v1["chat.message"]({ sessionID: "s1", agent: "herdorc" })
const ok = plugin.id && hook
  && await refused(v2("herdorc", "herdr server stop")) && !(await refused(v2("build", "herdr server stop")))
  && !(await refused(v2("herdorc", "ls")))
  && await refused(() => v1["tool.execute.before"]({ tool: "bash", sessionID: "s1" }, { args: { command: "herdr server stop" } }))
process.exit(ok ? 0 : 1)
EOF
check "opencode guard plugin refuses through setup() (2.x) and server() (1.x)" "node '$T/opencode-plugin.mjs' '$HOME/.config/opencode/plugins/herdr-orchestrators-guard.js'"
check "grok hooks: a hooks file of ours, guard --format grok on Bash" "python3 -c \"import json;h=json.load(open('$HOME/.grok/hooks/herdr-orchestrators.json'))['hooks']['PreToolUse'];assert len(h)==1 and h[0]['matcher']=='Bash' and h[0]['hooks'][0]['command'].endswith('guard.py --format grok')\""
check "pi guard extension: tool_call on bash, guard --format pi with the conversation, asks in pi's dialog" "grep -q 'pi.on(\"tool_call\"' $HOME/.pi/agent/extensions/herdr-orchestrators-guard.ts && grep -q '\"--format\", \"pi\"' $HOME/.pi/agent/extensions/herdr-orchestrators-guard.ts && grep -q 'ctx.ui.confirm' $HOME/.pi/agent/extensions/herdr-orchestrators-guard.ts && grep -q 'sessionManager?.getSessionId' $HOME/.pi/agent/extensions/herdr-orchestrators-guard.ts"
check "a rerun adds no second guard" "I >/dev/null && [ \$(grep -c guard.py $HOME/.codex/hooks.json) = 1 ] && [ \$(grep -c guard.py $HOME/.cursor/hooks.json) = 1 ] && [ \$(grep -c guard.py $HOME/.gemini/config/hooks.json) = 1 ]"
# Command parity: agy, codex and cursor get the commands as user-only skills, in one shared folder.
SK=$HOME/.agents/skills/hcorc-panes
check "command skills: user-only, preflight as a step, arguments named" "[ -L $SK/SKILL.md ] && grep -q '^disable-model-invocation: true' $SK/SKILL.md && grep -q 'orc.py --as hcorc preflight hcorc. with your shell tool' $SK/SKILL.md && grep -q 'panes <arguments>' $SK/SKILL.md && ! grep -q 'ARGUMENTS' $SK/SKILL.md && grep -q 'allow_implicit_invocation: false' $SK/agents/openai.yaml"
check "command skills shared by agy, codex, cursor and grok" "[ \$(python3 -c \"import json;m=json.load(open('$HOME/.local/state/orc/installs.json'));print(sum('$SK/SKILL.md' in e['files'] for k,e in m.items() if k.split('|')[0] in ('agy','codex','cursor','grok')))\") = 4 ]"
PT=$HOME/.pi/agent/prompts
check "pi commands: prompt templates that keep \$ARGUMENTS and run the preflight as a step" "grep -q 'panes [$]ARGUMENTS' $PT/hcorc-panes.md && grep -q 'preflight hcorc. with your shell tool' $PT/hcorc-panes.md && ! grep -q '!.' $PT/hcorc-panes.md && grep -q '^argument-hint:' $PT/hcorc-panes.md"
check "pi /<name> loads the orchestrator prompt and keeps the request typed after it" "grep -q 'request (empty when none): [$]ARGUMENTS' $PT/hcorc.md && grep -q '^argument-hint:' $PT/hcorc.md && ! grep -q 'ARGUMENTS' $HOME/.cursor/skills/hcorc/SKILL.md"
check "pi /<name> loads the orchestrator prompt; the prompt has pi's vocabulary" "grep -q '$HOME/.pi/agent/herdr-orchestrators/hcorc.md' $PT/hcorc.md && grep -q '# Tool vocabulary (pi)' $HOME/.pi/agent/herdr-orchestrators/hcorc.md && grep -q 'leave .Internal subagent. out' $HOME/.pi/agent/herdr-orchestrators/hcorc.md && grep -q 'prompt templates; the user types ./<name>.' $HOME/.pi/agent/herdr-orchestrators/hcorc.md"
check "grok prompt: its tools, its launch, commands as /skills" "grep -q '# Tool vocabulary (Grok Build)' $HOME/.grok/agents/hcorc.md && grep -q 'ask_user_question' $HOME/.grok/agents/hcorc.md && grep -q 'spawn_subagent' $HOME/.grok/agents/hcorc.md && grep -q 'grok --agent hcorc' $HOME/.grok/agents/hcorc.md && grep -q '/hcorc-status' $HOME/.grok/agents/hcorc.md"
check "codex prompt names its commands with \$" "grep -q 'hcorc-cleanup' $HOME/.codex/hcorc.config.toml && grep -q '[$]hcorc-cleanup' $HOME/.codex/hcorc.config.toml && grep -q 'the user types .[$]<name>.' $HOME/.codex/hcorc.config.toml"
check "no prompt ties its waits to a 5-minute cache (CLI and plan dependent)" "! grep -l -i 'prompt cache' $HOME/.claude/agents/hcorc.md $HOME/.claude/agents/herdorc.md $HOME/.config/opencode/agents/herdorc.md $HOME/.codex/hcorc.config.toml $HOME/.gemini/config/agents/herdorc/agent.md >/dev/null && grep -q 'keep you reachable' $HOME/.codex/hcorc.config.toml"
check "the flow command in every CLI: claude, opencode, skills" "grep -q 'orc.py flow' $HOME/.claude/commands/hcorc-flow.md && grep -q 'orc.py --as herdorc flow' $HOME/.config/opencode/commands/herdorc-flow.md && grep -q 'orc.py --as hcorc flow. with your shell tool' $HOME/.agents/skills/hcorc-flow/SKILL.md && grep -q 'hcorc-flow' $HOME/.claude/agents/hcorc.md"
check "agy prompt: commands as /skills, guard text" "grep -q '/herdorc-status' $HOME/.gemini/config/agents/herdorc/agent.md && grep -q 'A guard hook' $HOME/.gemini/config/agents/herdorc/agent.md"
check "claude prompt: hooks text, own vocabulary, no --as" "grep -q 'A guard hook (.shared/bin/guard.py.)' $HOME/.claude/agents/hcorc.md && ! grep -q 'The guard knows you are' $HOME/.claude/agents/hcorc.md && grep -q '# Tool vocabulary (Claude Code)' $HOME/.claude/agents/hcorc.md && ! grep -q -- '--as hcorc' $HOME/.claude/agents/hcorc.md"
check "opencode prompt: glossary, --as, guard text, mode primary" "grep -q '# Tool vocabulary (OpenCode)' $HOME/.config/opencode/agents/hcorc.md && grep -q -- 'orc.py --as hcorc' $HOME/.config/opencode/agents/hcorc.md && grep -q 'A guard hook' $HOME/.config/opencode/agents/hcorc.md && grep -q 'The guard knows you are hcorc' $HOME/.config/opencode/agents/hcorc.md && ! grep -q 'No hook enforces' $HOME/.config/opencode/agents/hcorc.md && grep -q '^mode: primary' $HOME/.config/opencode/agents/hcorc.md"
check "opencode read-only role denies edit, worker does not" "grep -q 'effect: deny' $HOME/.config/opencode/agents/review-risk.md && ! grep -q 'permissions' $HOME/.config/opencode/agents/gentle-ai-worker.md"
check "opencode command runs under its agent" "grep -q '^agent: herdorc' $HOME/.config/opencode/commands/herdorc-panes.md"
check "agy roles: subagent only, exact tools" "grep -q '^mainAgent: false' $HOME/.gemini/config/agents/review-risk/agent.md && grep -q 'run_command' $HOME/.gemini/config/agents/review-risk/agent.md && ! grep -q -E 'mcp__|Bash' $HOME/.gemini/config/agents/review-risk/agent.md"
check "agy orchestrators list their tools (an omitted list is read-only): shell, ask, subagents" "python3 -c \"
import re; t=open('$HOME/.gemini/config/agents/hcorc/agent.md').read(); fm=t.split('---')[1]
tools=re.findall(r'^  - (\\S+)', fm, re.M)
assert {'run_command','manage_task','ask_question','invoke_subagent','read_file','edit_file','write_file'} <= set(tools), tools\""
check "agy agents use only agy's current tool names" "! grep -h -E '^  - (view_file|list_dir|grep_search|find_by_name|replace_file_content|write_to_file|read_url_content|command_status)\$' $HOME/.gemini/config/agents/*/agent.md && ! grep -q command_status $HOME/.gemini/config/agents/hcorc/agent.md"
check "herdorc embeds the herdr skill" "grep -q 'The \`herdr\` skill follows' $HOME/.gemini/config/agents/herdorc/agent.md"
# tomllib is Python 3.11+; the scripts support 3.9, so older Pythons get a smaller check.
if python3 -c 'import tomllib' 2>/dev/null; then
check "codex TOML parses; roles carry no sandbox_mode (Codex ignores it for roles)" "python3 -c \"
import tomllib;h='$HOME/.codex'
w=tomllib.load(open(h+'/agents/gentle-ai-worker.toml','rb'));r=tomllib.load(open(h+'/agents/review-risk.toml','rb'));p=tomllib.load(open(h+'/hcorc.config.toml','rb'))
assert 'sandbox_mode' not in w and 'sandbox_mode' not in r and r['name']=='review-risk'
assert 'Tool vocabulary (Codex CLI)' in p['developer_instructions']\""
else
check "codex roles carry no sandbox_mode (no tomllib)" "! grep -q '^sandbox_mode' $HOME/.codex/agents/gentle-ai-worker.toml $HOME/.codex/agents/review-risk.toml"
fi
# The agy bug (an agent left with read-only tools) must not happen elsewhere: no orchestrator
# file narrows its tools, so each CLI gives it the shell, ask and subagent tools it has.
check "orchestrators never narrow their tools in opencode, codex, cursor, grok or pi" "! grep -q -E '^(tools|disallowedTools):' $HOME/.grok/agents/hcorc.md $HOME/.grok/agents/review-risk.md && ! grep -q -E '^(tools|excludeTools):' $PT/hcorc.md && ! grep -q -E '^(tools|permissions|permission):' $HOME/.config/opencode/agents/hcorc.md $HOME/.config/opencode/agents/herdorc.md && ! grep -q -E '^\\[features\\]|shell_tool|^sandbox_mode' $HOME/.codex/hcorc.config.toml $HOME/.codex/herdorc.config.toml && ! grep -q -E '^(tools|readonly):' $HOME/.cursor/skills/hcorc/SKILL.md"
check "codex vocabulary: update_plan is optional, fork_turns only when offered" "grep -q 'update_plan\\\`, when it is available' $HOME/.codex/hcorc.config.toml && grep -q 'when the tool offers it' $HOME/.codex/hcorc.config.toml"
check "cursor skill points at its prompt; read-only role" "grep -q \"$HOME/.cursor/skills/hcorc/prompt.md\" $HOME/.cursor/skills/hcorc/SKILL.md && grep -q '^readonly: true' $HOME/.cursor/agents/review-risk.md && ! grep -q readonly $HOME/.cursor/agents/gentle-ai-worker.md"
check "no unfilled placeholders or conditionals anywhere" "! grep -r -l -E '\{\{[A-Z_]+\}\}|<!-- (if:|endif)' '$ORC_DIST'"

# 3. rerun is a no-op; a pull that changes a prompt rewrites the target, not the link
check "rerun changes nothing" "I | grep -q '^\[claude\] updated 0 of'"
check "rerun keeps one guard hook" "[ \$(grep -c 'shared/bin/guard.py' '$S') = 1 ]"
echo stale > "$ORC_DIST/home/.claude/agents/hcorc.md"
check "a changed target is regenerated behind the same link" "I | grep -q '^\[claude\] updated 1 of' && grep -q 'Tool vocabulary' $HOME/.claude/agents/hcorc.md && [ -L $HOME/.claude/agents/hcorc.md ]"
rm "$ORC_DIST/home/.claude/agents/review-risk.md"
check "status flags a broken link" "python3 '$REPO/install.py' --status | grep '^claude ' | grep -q 'BROKEN=1'"
check "rerun repairs it" "I >/dev/null && [ -s $HOME/.claude/agents/review-risk.md ]"

# 4. project scope + a file we did not write
mkdir -p "$T/proj/.opencode/agents"; echo "mine" > "$T/proj/.opencode/agents/hcorc.md"
OUT=$(I --scope project --project "$T/proj" 2>&1)
check "foreign file blocks that CLI only" "echo \"\$OUT\" | grep -q 'opencode\] not installed' && [ \"\$(cat $T/proj/.opencode/agents/hcorc.md)\" = mine ] && [ -s $T/proj/.claude/agents/hcorc.md ]"
check "project claude hooks are absolute (not this repo)" "grep -q '$REPO/shared/bin/guard.py' $T/proj/.claude/settings.json"
check "--force overwrites it" "I --scope project --project '$T/proj' --cli opencode --force >/dev/null && grep -q 'mode: primary' $T/proj/.opencode/agents/hcorc.md"
check "codex profiles shared by both scopes" "[ -s $HOME/.codex/herdorc.config.toml ]"

# 5. --agents narrows and removes the dropped one
I --agents hcorc >/dev/null
check "dropped orchestrator removed, roles kept" "[ ! -e $HOME/.claude/agents/herdorc.md ] && [ ! -e $HOME/.gemini/config/agents/herdorc ] && [ -s $HOME/.claude/agents/review-risk.md ]"

# 6. uninstall
I --uninstall >/dev/null
check "global uninstall removes our links" "[ ! -L $HOME/.claude/agents/hcorc.md ] && [ ! -e $HOME/.cursor/skills/hcorc ] && [ ! -e $HOME/.gemini/config/agents/review-risk ]"
check "and the generated files behind them" "[ ! -e '$ORC_DIST/home/.claude/agents/hcorc.md' ] && [ ! -e '$ORC_DIST/home/.cursor' ]"
check "codex profile kept while the project install uses it" "[ -s $HOME/.codex/hcorc.config.toml ]"
check "hooks removed, user settings kept" "! grep -q 'shared/bin/guard.py' '$S' && grep -q mine.sh '$S' && grep -q dark '$S'"
check "every CLI's guard removed, the user's hooks kept" "! grep -q guard.py $HOME/.codex/hooks.json $HOME/.cursor/hooks.json $HOME/.gemini/config/hooks.json && grep -q mine-codex.sh $HOME/.codex/hooks.json && grep -q mine-cursor.sh $HOME/.cursor/hooks.json && grep -q mine-agy.sh $HOME/.gemini/config/hooks.json"
check "command skills and the opencode plugin removed, skill folders too" "[ ! -e $HOME/.agents/skills/hcorc-panes ] && [ ! -e $HOME/.config/opencode/plugins/herdr-orchestrators-guard.js ]"
check "grok hooks file, grok agents, pi extension and prompts removed" "[ ! -e $HOME/.grok/hooks/herdr-orchestrators.json ] && [ ! -e $HOME/.grok/agents/hcorc.md ] && [ ! -e $HOME/.pi/agent/extensions/herdr-orchestrators-guard.ts ] && [ ! -e $HOME/.pi/agent/prompts/hcorc.md ]"
I --uninstall --scope project --project "$T/proj" >/dev/null
check "project uninstall removes the rest" "[ ! -e $T/proj/.claude/agents/hcorc.md ] && [ ! -e $HOME/.codex/hcorc.config.toml ]"
check "status empty" "python3 '$REPO/install.py' --status | grep -q 'no installs'"

# 7. the Claude-only mods: planned for claude, never for another CLI
if [ -f "$REPO/.claude-plugin/marketplace.json" ] && command -v claude >/dev/null; then
  check "dry-run plans the mod plugins for claude" "python3 '$REPO/install.py' --cli claude --dry-run | grep -q 'would run: claude plugin install'"
  check "no mods for other CLIs" "! python3 '$REPO/install.py' --cli opencode,agy,codex,cursor --dry-run | grep -q 'claude plugin'"
fi

# 8. a broken settings.json aborts without writing
echo '{oops' > "$S"
check "invalid settings.json refused" "! I --cli claude >/dev/null 2>&1 && [ \"\$(cat '$S')\" = '{oops' ]"
echo '{"hooks": {"PreToolUse": null}}' > "$S"
check "a hooks event that is not a list is refused before any link" "! I --cli claude >/dev/null 2>&1 && [ ! -e $HOME/.claude/agents/hcorc.md ] && grep -q null '$S'"
echo '{"hooks": {"PreToolUse": [{"matcher": "Bash", "hooks": [{"type": "command", "command": true}]}]}}' > "$S"
check "a hook whose command is not text is refused before any link" "! I --cli claude >/dev/null 2>&1 && [ ! -e $HOME/.claude/agents/hcorc.md ] && grep -q true '$S'"
echo '{}' > "$S"; I --cli claude >/dev/null; echo '{oops' > "$S"
check "uninstall with broken settings keeps the record" "I --cli claude --uninstall | grep -q 'hooks left in place' && python3 '$REPO/install.py' --status | grep -q '^claude ' && [ ! -L $HOME/.claude/agents/hcorc.md ]"
echo '{}' > "$S"
check "and a later uninstall removes the hooks and the record" "I --cli claude --uninstall | grep -q 'hooks removed' && ! grep -q guard.py '$S' && ! python3 '$REPO/install.py' --status | grep -q '^claude '"
check "save_manifest keeps entries another run saved meanwhile" "python3 -c \"
import json, sys; sys.path.insert(0, '$REPO'); import install as I
m = I.load_manifest(); m['mine|x|y'] = {'files': []}
p = I.manifest_path(); p.parent.mkdir(parents=True, exist_ok=True)
other = I.read_manifest(); other['theirs|x|y'] = {'files': []}; p.write_text(json.dumps(other))
I.save_manifest(m); d = json.loads(p.read_text()); assert 'mine|x|y' in d and 'theirs|x|y' in d, d
m.pop('mine|x|y'); I.save_manifest(m); d = json.loads(p.read_text()); assert 'mine|x|y' not in d and 'theirs|x|y' in d, d
d.pop('theirs|x|y'); p.write_text(json.dumps(d))\""
check "Skills bar: a reinstall puts the button back beside a third-party sibling" "python3 -c \"
import sys; sys.path.insert(0, '$REPO'); import install as I
t = {'id': 'w', 'type': 'column', 'children': [{'id': 'orc-skills-bar', 'type': 'row', 'children': [{'id': 'tabs', 'type': 'block'}, {'id': 'other', 'type': 'block'}]}, {'id': 'work-body', 'type': 'row', 'children': []}]}
kids = lambda: [c['id'] for c in I.herdr_find(t, 'orc-skills-bar')[0]['children']]
assert I.herdr_patch(t); assert kids() == ['tabs', 'other', 'orc-skills-toggle'], kids()
assert I.herdr_patch(t); assert kids().count('orc-skills-toggle') == 1\""
check "Skills bar: held in a tabs-row column that takes its height; uninstall gives the tab bar back" "python3 -c \"
import sys, json, copy; sys.path.insert(0, '$REPO'); import install as I
tabs = {'id': 'tabs', 'type': 'block', 'size': {'px': 42}, 'window_drag': True, 'content': {'mod': 'tabs'}}
t = {'id': 'w', 'type': 'column', 'children': [tabs, {'id': 'work-body', 'type': 'row', 'children': []}]}
orig = copy.deepcopy(t)
assert I.herdr_patch(t); row, parent = I.herdr_find(t, 'tabs-row')
assert parent['id'] == 'w' and row['type'] == 'column' and row['size'] == {'px': 42}, row
assert [c['id'] for c in row['children']] == ['orc-skills-bar'] and row['children'][0]['size'] == {'weight': 1}, row
once = json.dumps(t); assert I.herdr_patch(t) and json.dumps(t) == once
